solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
bool cipher_key_valid(const char *k) {
    if (!*k)
        return false;
    for (; *k; k++)
        if (*k < 'a' || *k > 'z')
            return false;
    return true;
}
static bool code(const char *k, const char *t, char *o, int sign) {
    if (!cipher_key_valid(k))
        return false;
    size_t n = strlen(k);
    for (size_t i = 0; t[i]; i++)
        o[i] = (char)('a' + (t[i] - 'a' + sign * (k[i % n] - 'a') + 26) % 26);
    o[strlen(t)] = 0;
    return true;
}
bool cipher_encode(const char *k, const char *t, char *o) { return code(k, t, o, 1); }
bool cipher_decode(const char *k, const char *t, char *o) { return code(k, t, o, -1); }
void cipher_random_key(char *out, size_t n, uint64_t *s) {
    for (size_t i = 0; i < n; i++) {
        *s = *s * 6364136223846793005ULL + 1;
        out[i] = (char)('a' + (*s >> 32) % 26);
    }
    out[n] = 0;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    char o[200], d[200];
    assert(cipher_encode("abc", "aaaaaaaa", o) && !strcmp(o, "abcabcab"));
    assert(cipher_decode("abc", o, d) && !strcmp(d, "aaaaaaaa"));
    assert(cipher_encode("z", "z", o) && !strcmp(o, "y"));
    assert(!cipher_key_valid("") && !cipher_key_valid("ABC") &&
           !cipher_key_valid("abc1"));
    uint64_t seed = 1;
    cipher_random_key(o, 100, &seed);
    assert(strlen(o) == 100 && cipher_key_valid(o));

    return 0;
}
